import os
import hashlib
import hmac
import unicodedata
from pathlib import PurePosixPath
from typing import Optional, Tuple
import secrets
import re

# Configuration
BASE_STORAGE_DIR = "/var/app/storage/documents"
MAX_PATH_DEPTH = 5
ALLOWED_EXTENSIONS = {".pdf", ".docx", ".txt", ".xlsx", ".png", ".jpg"}
HMAC_SECRET = secrets.token_bytes(32)


class AccessToken:
    """Represents a validated access token with user context."""
    def __init__(self, user_id: str, org_id: str, role: str):
        self.user_id = user_id
        self.org_id = org_id
        self.role = role


def verify_token(token_str: str) -> Optional[AccessToken]:
    """Verify HMAC-signed token and extract claims."""
    try:
        parts = token_str.split(".")
        if len(parts) != 3:
            return None
        payload, timestamp, signature = parts
        expected_sig = hmac.new(
            HMAC_SECRET,
            f"{payload}.{timestamp}".encode(),
            hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(signature, expected_sig):
            return None
        # Parse payload
        fields = payload.split(":")
        if len(fields) != 3:
            return None
        return AccessToken(user_id=fields[0], org_id=fields[1], role=fields[2])
    except Exception:
        return None


def sanitize_filename(filename: str) -> str:
    """Remove null bytes and control characters from filename."""
    # Strip null bytes
    filename = filename.replace("\x00", "")
    # Remove control characters (0x00-0x1F, 0x7F)
    filename = re.sub(r'[\x00-\x1f\x7f]', '', filename)
    return filename


def check_path_traversal(filepath: str) -> bool:
    """Check if path contains traversal sequences.
    Returns True if path is SAFE, False if traversal detected."""
    # Check for obvious traversal patterns
    if ".." in filepath:
        return False
    if filepath.startswith("/"):
        return False
    if "\\" in filepath:
        return False
    # Check for encoded traversal
    if "%2e" in filepath.lower() or "%2f" in filepath.lower():
        return False
    # Verify path depth
    parts = filepath.split("/")
    if len(parts) > MAX_PATH_DEPTH:
        return False
    return True


def validate_extension(filename: str) -> bool:
    """Verify file has an allowed extension."""
    _, ext = os.path.splitext(filename)
    return ext.lower() in ALLOWED_EXTENSIONS


def normalize_for_storage(filepath: str) -> str:
    """Normalize unicode characters in filepath for consistent storage.
    Uses NFKC normalization to handle equivalent unicode representations."""
    return unicodedata.normalize("NFKC", filepath)


def resolve_document_path(org_id: str, filepath: str) -> str:
    """Resolve the full filesystem path for a document."""
    # Construct org-scoped path
    org_dir = os.path.join(BASE_STORAGE_DIR, org_id)
    full_path = os.path.join(org_dir, filepath)
    return full_path


def get_document(token: AccessToken, requested_path: str) -> Tuple[bool, str]:
    """Main document retrieval function.

    Security pipeline:
    1. Sanitize input (null bytes, control chars)
    2. Validate path traversal patterns
    3. Validate file extension
    4. Normalize unicode for storage lookup
    5. Resolve and verify final path
    """
    # Step 1: Sanitize
    clean_path = sanitize_filename(requested_path)

    # Step 2: Check traversal BEFORE normalization
    if not check_path_traversal(clean_path):
        return (False, "Path traversal detected")

    # Step 3: Validate extension
    if not validate_extension(clean_path):
        return (False, "File type not allowed")

    # Step 4: Normalize unicode for consistent storage access
    # This ensures that equivalent unicode representations map to the same file
    normalized_path = normalize_for_storage(clean_path)

    # Step 5: Resolve final path within org directory
    final_path = resolve_document_path(token.org_id, normalized_path)

    # Step 6: Read and return document
    try:
        if not os.path.isfile(final_path):
            return (False, "Document not found")
        with open(final_path, "r") as f:
            content = f.read()
        return (True, content)
    except (IOError, OSError) as e:
        return (False, f"Error reading document: {str(e)}")


def list_documents(token: AccessToken, directory: str) -> Tuple[bool, list]:
    """List documents in a directory within the org scope."""
    clean_dir = sanitize_filename(directory)

    if not check_path_traversal(clean_dir):
        return (False, [])

    # Normalize for storage
    normalized_dir = normalize_for_storage(clean_dir)

    dir_path = resolve_document_path(token.org_id, normalized_dir)

    try:
        if not os.path.isdir(dir_path):
            return (False, [])
        entries = os.listdir(dir_path)
        return (True, [e for e in entries if validate_extension(e)])
    except (IOError, OSError):
        return (False, [])


# Request handler
def handle_request(method: str, path: str, headers: dict, body: dict) -> dict:
    """HTTP request handler for document API."""
    # Authenticate
    auth_header = headers.get("Authorization", "")
    if not auth_header.startswith("Bearer "):
        return {"status": 401, "body": "Unauthorized"}

    token = verify_token(auth_header[7:])
    if token is None:
        return {"status": 401, "body": "Invalid token"}

    if method == "GET" and path.startswith("/api/documents/"):
        doc_path = path[len("/api/documents/"):]
        success, result = get_document(token, doc_path)
        if success:
            return {"status": 200, "body": result}
        return {"status": 404, "body": result}

    elif method == "GET" and path.startswith("/api/list/"):
        dir_path = path[len("/api/list/"):]
        success, entries = list_documents(token, dir_path)
        if success:
            return {"status": 200, "body": entries}
        return {"status": 404, "body": "Directory not found"}

    return {"status": 404, "body": "Not found"}
